function work(seed: Seed): HvacA2ExternalWorkSpec {
  const [
    slug, titleRu, systemCluster, operationClass, technologyClass, prototypeMaterial,
    complexity, primaryUom, sourceId, sourcePage, sourceSection, sourceTable, sourceItem,
    components, requiredInputs, scopeInclusions = [], scopeExclusions = DEFAULT_EXCLUSIONS,
    crossDomainInterfaces = DEFAULT_INTERFACES,
  ] = seed;
  return Object.freeze({
    catalogId: `external-hvac:a2:${slug}:r4`,
    titleRu,
    systemCluster,
    operationClass,
    technologyClass,
    prototypeMaterial,
    complexity: FACTUAL_COMPLEXITY_CORRECTIONS[slug] ?? complexity,
    primaryUom,
    sourceId,
    sourcePage,
    sourceSection,
    sourceTable,
    sourceItem,
    components: Object.freeze([
      ...components,
      ...(PHYSICAL_COMPLETENESS_COMPONENTS[slug] ?? []),
      ...(HVAC_A2_STRICT_DEPTH_REPAIR_COMPONENTS[slug] ?? []),
    ]),
    requiredInputs: Object.freeze([...requiredInputs]),
    scopeInclusions: Object.freeze([...scopeInclusions]),
    scopeExclusions: Object.freeze([...scopeExclusions]),
    crossDomainInterfaces: Object.freeze([...crossDomainInterfaces]),
  });
}

