export const HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS: readonly HvacA2ExternalWorkSpec[] = Object.freeze(
  seeds.map(work).sort((left, right) => left.catalogId.localeCompare(right.catalogId)),
);

export const HVAC_A2_EXTERNAL_NON_DEMOLITION_COUNT = HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS.length;

const catalogIds = new Set(HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS.map((item) => item.catalogId));
if (catalogIds.size !== HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS.length) {
  throw new Error("HVAC_A2_EXTERNAL_DUPLICATE_CATALOG_ID");
}
for (const item of HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS) {
  if (item.components.length < 4) throw new Error(`HVAC_A2_EXTERNAL_PHYSICAL_SCOPE_RED:${item.catalogId}`);
  if (item.requiredInputs.length < 4) throw new Error(`HVAC_A2_EXTERNAL_INPUT_SCOPE_RED:${item.catalogId}`);
  if (!item.sourceTable || !item.sourceItem || item.sourcePage < 1) {
    throw new Error(`HVAC_A2_EXTERNAL_LOCATOR_RED:${item.catalogId}`);
  }
}

export function hvacA2SpecForCatalogId(catalogId: string): HvacA2ExternalWorkSpec | null {
  return HVAC_A2_EXTERNAL_NON_DEMOLITION_SPECS.find((item) => item.catalogId === catalogId) ?? null;
}
